#!/usr/bin/env bash
# Logs into the live RocketChat container as the provisioned admin and
# writes a real authToken/userId into external Specmatic examples that
# need them, across every spec file being contract-tested (not just
# authentication.yaml -- every operation in the RocketChat REST API uses
# the same two headers). RocketChat issues a fresh admin token on every
# new container, so these example files are gitignored and regenerated by
# this script right before a test run -- never committed as static
# credentials.
#
# Only external example files are touched. No spec file is ever edited --
# they declare X-Auth-Token/X-User-Id as plain header parameters (or a
# shared $ref component with the same names), and Specmatic's
# external-examples mechanism
# (https://docs.specmatic.io/features/external_examples) is the
# spec-respecting way to supply concrete values for those headers.
set -euo pipefail

BASE_URL="${RC_BASE_URL:-http://localhost:3000}"
ADMIN_USER="${ADMIN_USERNAME:-admin}"
ADMIN_PASS="${RC_ADMIN_PASS:-SpecmaticAdmin123!}"
EXAMPLES_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../examples" && pwd)"

login_response=$(curl -sf -X POST "${BASE_URL}/api/v1/login" \
  -H "Content-Type: application/json" \
  -d "{\"user\":\"${ADMIN_USER}\",\"password\":\"${ADMIN_PASS}\"}")

auth_token=$(printf '%s' "$login_response" | python3 -c 'import json,sys; print(json.load(sys.stdin)["data"]["authToken"])')
user_id=$(printf '%s' "$login_response" | python3 -c 'import json,sys; print(json.load(sys.stdin)["data"]["userId"])')

if [ -z "$auth_token" ] || [ -z "$user_id" ]; then
  echo "Failed to extract authToken/userId from login response" >&2
  exit 1
fi

# http-response.body here is only used to type-check this example file at
# load time (the actual test assertion compares the LIVE response against
# the spec, not against this body) -- so it's the spec's own declared
# schema shape (copied from authentication.yaml's "User profile" example),
# not a live-captured one. A live-captured body would carry undocumented
# fields (see README "Issues found and fixed") and fail this file's own
# load-time type-check for the same reason those fields fail the real test.
cat > "${EXAMPLES_DIR}/get-me.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/me",
    "method": "GET",
    "headers": {
      "X-Auth-Token": "${auth_token}",
      "X-User-Id": "${user_id}"
    }
  },
  "http-response": {
    "status": 200,
    "body": {
      "_id": "aobEdbYhXfu5hkeqG",
      "name": "Example User",
      "emails": [{ "address": "example@example.com", "verified": true }],
      "status": "offline",
      "statusConnection": "offline",
      "username": "example",
      "utcOffset": 0,
      "active": true,
      "roles": ["user", "admin"],
      "settings": { "preferences": {} },
      "customFields": { "twitter": "@userstwi" },
      "avatarUrl": "http://localhost:3000/avatar/test",
      "success": true
    }
  }
}
EOF

echo "Wrote ${EXAMPLES_DIR}/get-me.json with a live auth token/userId."

# content-management.yaml -- read-only (GET) operations. Response bodies
# below are schema shapes copied from the spec's own inline examples, same
# reasoning as get-me.json above.
cat > "${EXAMPLES_DIR}/emoji-custom-all.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/emoji-custom.all",
    "method": "GET",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "emojis": [{ "_id": "6542e83aa2f73c7460e18efb", "name": "happy", "aliases": ["happy-gang"], "extension": "png", "_updatedAt": "2023-11-02T00:07:22.433Z" }],
      "count": 1, "offset": 0, "total": 1, "success": true
    }
  }
}
EOF

cat > "${EXAMPLES_DIR}/emoji-custom-list.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/emoji-custom.list",
    "method": "GET",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "emojis": {
        "update": [{ "_id": "S5XvYppoLrLd9JvQm", "name": "teste", "aliases": [], "extension": "jpg", "_updatedAt": "2019-02-18T16:48:35.119Z" }],
        "remove": [{ "_id": "2dbVBG434dnsdh23", "name": "teste3", "aliases": [], "extension": "jpg", "_updatedAt": "2019-02-18T16:48:35.119Z" }]
      },
      "success": true
    }
  }
}
EOF

cat > "${EXAMPLES_DIR}/custom-sounds-list.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-sounds.list",
    "method": "GET",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "sounds": [{ "_id": "65462caea2f73c7460e18f83", "name": "doremi", "extension": "mp3", "_updatedAt": "2023-11-04T11:36:14.171Z" }],
      "count": 1, "offset": 0, "total": 1, "success": true
    }
  }
}
EOF

cat > "${EXAMPLES_DIR}/custom-user-status-list.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-user-status.list",
    "method": "GET",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "statuses": [{ "_id": "63f61be0b000b6b6d86704c8", "name": "brb", "statusType": "away", "_updatedAt": "2023-02-22T13:42:56.811Z" }],
      "count": 1, "offset": 0, "total": 1, "success": true
    }
  }
}
EOF

# No custom sound is seeded on a fresh instance, so a real _id isn't
# available without first exercising custom-sounds.create (deferred --
# multipart/form-data upload, see README). This exercises the documented
# "not found" path instead, which is real, meaningful coverage on its own.
cat > "${EXAMPLES_DIR}/custom-sounds-getone-notfound.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-sounds.getOne",
    "method": "GET",
    "query": { "_id": "nonexistent-sound-id" },
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}" }
  },
  "http-response": {
    "status": 404,
    "body": { "success": false, "error": "Custom Sound not found." }
  }
}
EOF

echo "Wrote content-management.yaml read-only examples."

# custom-user-status create/update/delete: the only content-management
# write operations that are plain JSON (not multipart/form-data uploads --
# emoji-custom.*, custom-sounds.*, assets.* all require real file content
# and are deferred, see README). A unique name avoids "name already in
# use" on repeated script runs; a real status is seeded here via a live
# call so update/delete (below) have a real _id to act on -- the create
# example below issues its OWN separate real create call when Specmatic
# runs it, under a different unique name, so it doesn't collide with this
# seeded one.
STATUS_NAME="specmatic-seed-$(date +%s)"
seed_response=$(curl -sf -X POST "${BASE_URL}/api/v1/custom-user-status.create" \
  -H "Content-Type: application/json" \
  -H "X-Auth-Token: ${auth_token}" -H "X-User-Id: ${user_id}" \
  -d "{\"name\":\"${STATUS_NAME}\",\"statusType\":\"busy\"}")
seed_id=$(printf '%s' "$seed_response" | python3 -c 'import json,sys; print(json.load(sys.stdin)["customUserStatus"]["_id"])')

if [ -z "$seed_id" ]; then
  echo "Failed to seed a custom user status for update/delete examples" >&2
  exit 1
fi

cat > "${EXAMPLES_DIR}/custom-user-status-create.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-user-status.create",
    "method": "POST",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}", "Content-Type": "application/json" },
    "body": { "name": "specmatic-create-$(date +%s)-$$", "statusType": "busy" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "customUserStatus": { "_id": "65462e97a2f73c7460e18f84", "name": "caught up", "statusType": "busy", "_updatedAt": "2023-11-04T11:44:23.366Z" },
      "success": true
    }
  }
}
EOF

cat > "${EXAMPLES_DIR}/custom-user-status-update.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-user-status.update",
    "method": "POST",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}", "Content-Type": "application/json" },
    "body": { "_id": "${seed_id}", "name": "${STATUS_NAME}-renamed", "statusType": "away" }
  },
  "http-response": {
    "status": 200,
    "body": {
      "customUserStatus": { "_id": "${seed_id}", "name": "${STATUS_NAME}-renamed", "statusType": "away", "_updatedAt": "2023-11-04T11:51:28.353Z" },
      "success": true
    }
  }
}
EOF

cat > "${EXAMPLES_DIR}/custom-user-status-delete.json" <<EOF
{
  "http-request": {
    "path": "/api/v1/custom-user-status.delete",
    "method": "POST",
    "headers": { "X-Auth-Token": "${auth_token}", "X-User-Id": "${user_id}", "Content-Type": "application/json" },
    "body": { "customUserStatusId": "${seed_id}" }
  },
  "http-response": {
    "status": 200,
    "body": { "success": true }
  }
}
EOF

echo "Wrote custom-user-status create/update/delete examples (seeded _id: ${seed_id})."
